// AUTO-GENERATED by scripts/build-r-helpers.ts from rhelpers/*.R.
// Do not edit. Edit the .R sources and run `pnpm gen:rhelpers` to regenerate.

/**
 * The inline R helper definitions "Export R script" can emit — one entry per
 * `rhelpers/*.R` file, keyed by the name a fragment requests it by. Only the
 * helpers a script actually references are emitted into it (see exportR.ts).
 * They are plain rtracklayer/ggplot2 so a user (or an assistant) can read and
 * edit them in the emitted script without learning a bespoke package.
 */
export const HELPERS: Record<string, string> = {
  bam_base_quality: "# Per-base Phred quality for every reference-aligned base - the signal JBrowse's\n# perBaseQuality color-by paints. Reads QUAL (stored genomic-forward in BAM, so\n# no reverse-strand handling) and walks the CIGAR to map each M/=/X read base to\n# its reference column (I/S consume the read only, D/N/H the reference / nothing).\n# Returns data.frame(read_index, refpos [0-based], score [Phred int]); read_index\n# matches read_bam order so a base joins its pileup row via reads$row[bq$read_index].\nbam_base_quality <- function(uri, chrom, start, end) {\n  b <- scanBam(uri, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end)),\n    what = c(\"pos\", \"cigar\", \"qual\")))[[1]]\n  quals <- as(b$qual, \"IntegerList\")\n  out <- vector(\"list\", length(b$cigar))\n  for (i in seq_along(b$cigar)) {\n    q <- quals[[i]]; if (!length(q)) next\n    ops <- regmatches(b$cigar[i], gregexpr(\"[0-9]+[MIDNSHP=X]\", b$cigar[i]))[[1]]\n    if (!length(ops)) next\n    oplen <- as.integer(sub(\"[MIDNSHP=X]$\", \"\", ops)); opchr <- sub(\"^[0-9]+\", \"\", ops)\n    rp <- b$pos[i] - 1L; qp <- 1L; pos <- integer(0); sc <- integer(0)\n    for (k in seq_along(ops)) {\n      L <- oplen[k]; op <- opchr[k]\n      if (op %in% c(\"M\", \"=\", \"X\")) {\n        pos <- c(pos, rp:(rp + L - 1L)); sc <- c(sc, q[qp:(qp + L - 1L)])\n        rp <- rp + L; qp <- qp + L\n      } else if (op %in% c(\"I\", \"S\")) { qp <- qp + L\n      } else if (op %in% c(\"D\", \"N\")) { rp <- rp + L }\n    }\n    if (length(pos)) out[[i]] <- data.frame(read_index = i, refpos = pos, score = sc)\n  }\n  do.call(rbind, out)\n}",
  bam_clips: "# Soft/hard clips at each read's ends, from the first/last CIGAR op (S = soft,\n# H = hard). Returns data.frame(read_index, pos, type, length): 'pos' is the\n# 0-based reference position of the clip - a read's aligned start for a leading\n# clip, its aligned end for a trailing clip - marking where the read carries\n# unaligned sequence (a breakpoint signal, the same clip indicators JBrowse\n# draws). 'read_index' matches read_bam order (same region, same readGAlignments\n# order) so a clip bar joins its pileup row via reads$row[clips$read_index].\nbam_clips <- function(uri, chrom, start, end) {\n  ga <- readGAlignments(uri, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end))))\n  cig <- cigar(ga); rs <- start(ga) - 1L; re <- end(ga)\n  out <- vector(\"list\", length(ga))\n  for (i in seq_along(ga)) {\n    ops <- regmatches(cig[i], gregexpr(\"[0-9]+[MIDNSHP=X]\", cig[i]))[[1]]\n    if (!length(ops)) next\n    op <- sub(\"^[0-9]+\", \"\", ops); len <- as.integer(sub(\"[MIDNSHP=X]$\", \"\", ops))\n    n <- length(ops); ends <- list()\n    if (op[1] %in% c(\"S\", \"H\")) ends[[1]] <- data.frame(read_index = i, pos = rs[i], type = op[1], length = len[1])\n    if (op[n] %in% c(\"S\", \"H\")) ends[[2]] <- data.frame(read_index = i, pos = re[i], type = op[n], length = len[n])\n    out[[i]] <- do.call(rbind, ends)\n  }\n  do.call(rbind, out)\n}",
  bam_coverage: "# Per-base read depth over the region. drop.D.ranges = TRUE carves deletions (D)\n# out of the depth the same way JBrowse's coverage sweep does (both deletions and\n# skips reduce depth) - a plain coverage(ga) counts a deleted column as covered,\n# so the grey total would not dip at a deletion like the browser's does.\n# 'keep' is an optional logical vector in readGAlignments order - the same order\n# read_bam returns and read_index joins on - so read_filter's keep column subsets\n# exactly the reads the pileup draws. JBrowse applies \"Filter by\" in the adapter,\n# so every consumer of that read stream (pileup AND coverage) sees only reads\n# that pass; passing keep here is what keeps this panel honest with the pileup\n# above it. NULL counts every read.\n# An all-filtered region is safe: the BAM header's seqinfo rides along on the\n# GAlignments, so coverage() still yields this chrom's Rle, just all zeros.\nbam_coverage <- function(uri, chrom, start, end, keep = NULL) {\n  ga <- readGAlignments(uri, param = ScanBamParam(which = GRanges(chrom, IRanges(start + 1, end))))\n  if (!is.null(keep)) ga <- ga[keep]\n  cov <- coverage(grglist(ga, drop.D.ranges = TRUE))[[chrom]]\n  pos <- (start + 1):end\n  data.frame(pos = pos - 1L, depth = as.numeric(cov[pos]))\n}",
  bam_indels: "# CIGAR indels/gaps that break a read's aligned span - reference-consuming ops\n# that read_bam's start..end coordinates silently swallow (a read spanning a\n# deletion or intron looks like continuous sequence otherwise). Walks each read's\n# CIGAR: D = deletion, N = skip (spliced intron), I = insertion (does not consume\n# reference, so it sits at a single column). Returns data.frame(read_index,\n# refpos [0-based reference start of the op], length, type in {D,N,I}); refpos for\n# an insertion is the reference column it is anchored before. read_index matches\n# read_bam order (same region, same readGAlignments order) so a marker joins its\n# pileup row via reads$row[indels$read_index].\nbam_indels <- function(uri, chrom, start, end) {\n  ga <- readGAlignments(uri, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end))))\n  cig <- cigar(ga); refstart <- start(ga)\n  out <- vector(\"list\", length(ga))\n  for (i in seq_along(ga)) {\n    ops <- regmatches(cig[i], gregexpr(\"[0-9]+[MIDNSHP=X]\", cig[i]))[[1]]\n    if (!length(ops)) next\n    oplen <- as.integer(sub(\"[MIDNSHP=X]$\", \"\", ops)); opchr <- sub(\"^[0-9]+\", \"\", ops)\n    rp <- refstart[i]; pos <- integer(0); len <- integer(0); ty <- character(0)\n    for (k in seq_along(ops)) {\n      L <- oplen[k]; op <- opchr[k]\n      # record the indel at the current reference column (I sits between bases)\n      if (op %in% c(\"D\", \"N\", \"I\")) {\n        pos <- c(pos, rp - 1L); len <- c(len, L); ty <- c(ty, op)\n      }\n      # reference-consuming ops advance the column (I does not)\n      if (op %in% c(\"M\", \"=\", \"X\", \"D\", \"N\")) { rp <- rp + L }\n    }\n    if (length(pos)) out[[i]] <- data.frame(read_index = i, refpos = pos, length = len, type = ty)\n  }\n  do.call(rbind, out)\n}",
  bam_mismatches: "# Per-read mismatches, derived the way JBrowse's own adapter derives them: from\n# the MD tag where a read carries one, and against the reference where it does\n# not. MD is optional in BAM - plenty of aligners never write it, and samtools\n# calmd is a separate pass - so an MD-only walk draws a pileup with no SNP ticks\n# on those files and says nothing about it (BamAdapter.ts: `needsReference`,\n# seqFetchSpan.ts).\n#\n# MD path: walk the CIGAR to pair each aligned (M/=/X) reference column with its\n# read-sequence position, then walk the MD tag over those columns - a number\n# skips matches, a letter marks a mismatch (whose read base is read from SEQ),\n# ^SEQ marks a deleted stretch.\n#\n# Reference path: project the read onto reference coordinates with\n# sequenceLayer() and compare base by base. The projection writes a gap\n# character where the read deletes, which is not a mismatch and is dropped.\n#\n# 'ref' is the assembly's sequence file (indexed FASTA or 2bit); NULL/empty\n# means MD-less reads contribute nothing, which the exporter reports rather than\n# drawing a read as if it matched everywhere. 'read_index' indexes reads in the\n# same order read_bam returns them (same region, same readGAlignments order), so\n# a mismatch tick joins back to its pileup row via reads$row[mm$read_index].\n# refpos is 0-based.\nbam_mismatches <- function(uri, chrom, start, end, ref = NULL) {\n  ga <- readGAlignments(uri, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end)), what = \"seq\", tag = \"MD\"))\n  md <- as.character(mcols(ga)$MD)\n  seqs <- as.character(mcols(ga)$seq)\n  cig <- cigar(ga); refstart <- start(ga)\n  has_md <- !is.na(md)\n  # One read of the reference for every MD-less read in the region, not one per\n  # read: the same span-then-window shape seqFetchSpan uses on the JBrowse side.\n  refseq <- NULL; refoff <- 0L; proj <- NULL\n  if (any(!has_md) && !is.null(ref) && nzchar(ref)) {\n    span <- GRanges(chrom, IRanges(min(refstart[!has_md]), max(end(ga)[!has_md])))\n    refseq <- getSeq(open_reference(ref), span)[[1]]\n    refoff <- start(span)\n    # One projection for the whole set rather than one per read: sequenceLayer is\n    # vectorized, and it is deprecated (renamed to cigarillo::project_sequences\n    # in GenomicAlignments >= 1.45.5), so a per-read call also prints its\n    # deprecation warning once per read.\n    proj <- sequenceLayer(mcols(ga)$seq, cig, to = \"reference\")\n  }\n  out <- vector(\"list\", length(ga))\n  for (i in seq_along(ga)) {\n    if (has_md[i]) {\n      if (!grepl(\"[ACGTNacgtn]\", md[i])) next\n      ops <- regmatches(cig[i], gregexpr(\"[0-9]+[MIDNSHP=X]\", cig[i]))[[1]]\n      oplen <- as.integer(sub(\"[MIDNSHP=X]$\", \"\", ops))\n      opchr <- sub(\"^[0-9]+\", \"\", ops)\n      rp <- refstart[i]; qp <- 1L; ref_cols <- integer(0); read_cols <- integer(0)\n      for (k in seq_along(ops)) {\n        L <- oplen[k]; op <- opchr[k]\n        if (op %in% c(\"M\", \"=\", \"X\")) {\n          ref_cols <- c(ref_cols, rp:(rp + L - 1L))\n          read_cols <- c(read_cols, qp:(qp + L - 1L)); rp <- rp + L; qp <- qp + L\n        } else if (op %in% c(\"I\", \"S\")) { qp <- qp + L\n        } else if (op %in% c(\"D\", \"N\")) { rp <- rp + L }\n      }\n      toks <- regmatches(md[i], gregexpr(\"[0-9]+|\\\\^[A-Za-z]+|[A-Za-z]\", md[i]))[[1]]\n      mi <- 0L; pos <- integer(0); base <- character(0)\n      for (t in toks) {\n        if (grepl(\"^[0-9]+$\", t)) { mi <- mi + as.integer(t)\n        } else if (!startsWith(t, \"^\")) {\n          mi <- mi + 1L; pos <- c(pos, ref_cols[mi])\n          base <- c(base, substr(seqs[i], read_cols[mi], read_cols[mi]))\n        }\n      }\n      if (length(pos)) out[[i]] <- data.frame(read_index = i, refpos = pos - 1L, base = base)\n    } else if (!is.null(proj)) {\n      q <- strsplit(as.character(proj[[i]]), \"\")[[1]]\n      r <- strsplit(as.character(subseq(\n        refseq, refstart[i] - refoff + 1L, width = length(q))), \"\")[[1]]\n      d <- which(q != r & q != \"-\")\n      if (length(d)) out[[i]] <- data.frame(\n        read_index = i, refpos = refstart[i] + d - 2L, base = toupper(q[d]))\n    }\n  }\n  do.call(rbind, out)\n}",
  bam_modifications: "# Per-base modifications from the MM/ML tags (modBAM) - the signal JBrowse's\n# 'modifications'/methylation coloring shows, parsed reference-free from the tags\n# (no reference FASTA). For each MM group (e.g. \"C+m\" 5mC, \"A+a\" 6mA) walks the\n# comma-separated skip counts over the read's target bases to recover each\n# modified base, reads its ML probability (0..255 -> 0..1), and CIGAR-maps the\n# read position to the reference. Faithful to JBrowse's getModPositions:\n# reverse-strand reads complement the target base and count from the read 5' end;\n# combined codes like \"C+mh\" interleave ML per position. ML is a B:C array tag\n# that breaks readGAlignments' DataFrame, so this reads via scanBam (whose read\n# order matches read_bam's readGAlignments, so read_index joins to pileup rows).\n# Returns data.frame(read_index, refpos [0-based], modtype, prob, strand, base) -\n# 'base' is the MM group's target base as written in the tag (never complemented,\n# like getModPositions), which is what mod_coverage's modifiable/detectable\n# denominator keys off.\n#\n# The result also carries an \"mm_strands\" attribute: the \"<sign><type>\" pairs of\n# every MM group seen, INCLUDING groups whose calls all fell below min_prob, so\n# mod_simplex_types can tell simplex from duplex over the whole read set. It is\n# an attribute rather than a column because it must survive the threshold filter;\n# read it off the returned frame directly, since any row subset drops it.\n# The path goes to scanBam as a bare string, not through BamFile(): BamFile()\n# resolves the index by looking for a sibling file, which finds nothing over\n# http and leaves index = NA, so every remote modBAM - the usual way a JBrowse\n# track names one - died on \"valid 'index' file required\" while every other\n# helper here read the same url fine.\nbam_modifications <- function(uri, chrom, start, end, min_prob = 0.1) {\n  b <- scanBam(uri, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end)),\n    what = c(\"strand\", \"pos\", \"cigar\", \"seq\"),\n    tag = c(\"MM\", \"ML\", \"Mm\", \"Ml\")))[[1]]\n  mm_all <- if (!is.null(b$tag$MM)) b$tag$MM else b$tag$Mm\n  ml_all <- if (!is.null(b$tag$ML)) b$tag$ML else b$tag$Ml\n  if (is.null(mm_all)) return(NULL)\n  compl <- c(A = \"T\", T = \"A\", C = \"G\", G = \"C\", U = \"A\", N = \"N\")\n  seqs <- as.character(b$seq); strands <- as.character(b$strand)\n  out <- list(); seen <- character(0)\n  for (i in seq_along(mm_all)) {\n    mm <- mm_all[i]; if (is.na(mm) || mm == \"\") next\n    ml <- if (is.null(ml_all)) integer(0) else as.integer(ml_all[[i]])\n    isrev <- strands[i] == \"-\"\n    s <- strsplit(seqs[i], \"\", fixed = TRUE)[[1]]; n <- length(s)\n    # CIGAR read(1-based)->ref(1-based) column map, reference-forward orientation\n    ops <- regmatches(b$cigar[i], gregexpr(\"[0-9]+[MIDNSHP=X]\", b$cigar[i]))[[1]]\n    oplen <- as.integer(sub(\"[MIDNSHP=X]$\", \"\", ops)); opchr <- sub(\"^[0-9]+\", \"\", ops)\n    ref2 <- rep(NA_integer_, n); rp <- b$pos[i]; qp <- 1L\n    for (k in seq_along(ops)) {\n      op <- opchr[k]; L <- oplen[k]\n      if (op %in% c(\"M\", \"=\", \"X\")) {\n        ref2[qp:(qp + L - 1L)] <- rp:(rp + L - 1L); rp <- rp + L; qp <- qp + L\n      } else if (op %in% c(\"I\", \"S\")) { qp <- qp + L\n      } else if (op %in% c(\"D\", \"N\")) { rp <- rp + L }\n    }\n    mlbase <- 0L\n    for (g in strsplit(mm, \";\", fixed = TRUE)[[1]]) {\n      if (g == \"\") next\n      f <- strsplit(g, \",\", fixed = TRUE)[[1]]\n      h <- regmatches(f[1], regexec(\"([ACGTUN])([-+])([a-z]+|[A-Z]|[0-9]+)\", f[1]))[[1]]\n      if (length(h) < 4L) next\n      base <- h[2]; mmsign <- h[3]; typestr <- h[4]\n      deltas <- as.integer(f[-1]); ndelta <- length(deltas)\n      if (!ndelta) next\n      # combined lowercase codes (mh) are one type per char; a ChEBI number or a\n      # single uppercase ambiguity code is one type (mirrors getModPositions)\n      single <- utf8ToInt(substr(typestr, 1, 1))[1] < 97L || nchar(typestr) == 1L\n      types <- if (single) typestr else strsplit(typestr, \"\", fixed = TRUE)[[1]]\n      ntypes <- length(types)\n      seen <- c(seen, paste0(mmsign, types))\n      target <- if (isrev) compl[[base]] else base\n      idx <- if (base == \"N\") seq_len(n) else which(s == target)\n      if (isrev) idx <- rev(idx)                       # count from the read 5' end\n      sel <- idx[cumsum(deltas) + seq_len(ndelta)]     # ref-forward SEQ index, MM order\n      refp <- ref2[sel]\n      for (tj in seq_len(ntypes)) {\n        probs <- (ml[mlbase + tj + (seq_len(ndelta) - 1L) * ntypes] + 0.5) / 256\n        keep <- !is.na(refp) & !is.na(probs) & probs >= min_prob\n        if (any(keep)) out[[length(out) + 1L]] <- data.frame(\n          read_index = i, refpos = refp[keep] - 1L, modtype = types[tj],\n          prob = probs[keep], strand = if (isrev) -1L else 1L, base = base,\n          stringsAsFactors = FALSE)\n      }\n      mlbase <- mlbase + ndelta * ntypes\n    }\n  }\n  if (!length(out)) return(NULL)\n  res <- do.call(rbind, out)\n  attr(res, \"mm_strands\") <- unique(seen)\n  res\n}",
  bam_tag_values: "# One BAM tag's value per read, as character, in readGAlignments order - the same\n# order read_bam returns and read_index joins on, so it can be attached to the\n# reads frame as a column (reads$sort_tag) and survive the multi-region rbind.\n# Drives the \"tag\" sort (see sorted_pileup_layout). Mirrors JBrowse's\n# extractFeatureTagValue: a value is stringified, and a read lacking the tag\n# reads as \"\" rather than NA, so the sort treats it as 0 / \"\" like the browser.\nbam_tag_values <- function(uri, chrom, start, end, tag) {\n  ga <- readGAlignments(uri, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end)), tag = tag))\n  v <- mcols(ga)[[tag]]\n  out <- if (is.null(v)) rep(\"\", length(ga)) else as.character(v)\n  out[is.na(out)] <- \"\"\n  out\n}",
  base_colors: "# JBrowse's per-base mismatch colors (green A / blue C / orange G / red T /\n# brown N), used with scale_fill_identity so no legend and no second fill scale.\nbase_colors <- c(A = \"#4caf50\", C = \"#2196f3\", G = \"#ff9800\", T = \"#f44336\", N = \"#795548\")",
  bind_parts: "# Concatenate one entry from every region's `parts` list into the single frame a\n# panel draws. Each panel reads its regions in a loop and stashes that region's\n# frames in parts[[ri]]; this is the step that turns those per-region pieces into\n# one frame on the shared cumulative axis.\n#\n# A region that produced nothing for this entry stashed NULL and is dropped\n# rather than erroring - an ordinary case, since a track can have no features in\n# one region of a multi-region view (and a per-read overlay is NULL whenever no\n# read carried it). The result is NULL when no region produced any, which is why\n# a caller guards with `if (!is.null(x) && nrow(x))` before drawing it.\nbind_parts <- function(parts, name) {\n  do.call(rbind, Filter(Negate(is.null), lapply(parts, `[[`, name)))\n}",
  clip_colors: "# JBrowse's clip indicator colors: soft clip blue, hard clip red. Used with\n# scale_color_identity (a separate aesthetic from the read/mismatch fill scale).\nclip_colors <- c(S = \"#0000ff\", H = \"#ff0000\")",
  collapse_isoforms: "# Collapse each gene to a single transcript, reproducing the display's\n# \"Longest coding transcript\" gene glyph mode (geneGlyphMode). Without it the\n# panel draws every isoform a gene has, which at gene-scale zoom is what the\n# browser deliberately stops doing - a 6 kb window over one hg38 gene came out\n# as a solid block of stacked transcripts.\n#\n# \"Longest coding\" is the longest PROTEIN - summed CDS bp over the transcript's\n# subtree, deduped by (start, end) because duplicated CDS rows are a real GFF3\n# quirk and counting one twice would win it the pick - not the widest genomic\n# footprint, which an isoform with a big intron could take with a shorter\n# protein. A gene whose isoforms are all non-coding falls back to the widest\n# span. An exact tie resolves to the LATER isoform, matching the display.\n#\n# 'transcript_types' names the child types that count as isoforms; a gene with\n# no child of those types treats its direct children as the isoform list, as\n# getIsoforms does. Matched case-insensitively, like every other type test here.\ncollapse_isoforms <- function(f, transcript_types) {\n  if (is.null(f) || !nrow(f)) return(f)\n  fid <- ifelse(is.na(f$id), paste0(\"_f\", seq_len(nrow(f))), f$id)\n  by_parent <- split(seq_len(nrow(f)), f$parent)   # drops the parent-less roots\n  descendants <- function(id) {\n    out <- integer(0); stack <- id\n    while (length(stack)) {\n      kids <- by_parent[[stack[1]]]; stack <- stack[-1]\n      if (!is.null(kids)) { out <- c(out, kids); stack <- c(stack, fid[kids]) }\n    }\n    out\n  }\n  coding_bp <- function(idx) {\n    cds <- idx[tolower(f$type[idx]) == \"cds\"]\n    if (!length(cds)) return(0)\n    keep <- !duplicated(paste(f$start[cds], f$end[cds]))\n    sum(f$end[cds][keep] - f$start[cds][keep])\n  }\n  tt <- tolower(transcript_types)\n  drop <- integer(0)\n  for (root in fid[is.na(f$parent)]) {\n    kids <- by_parent[[root]]\n    if (is.null(kids) || length(kids) < 2) next\n    iso <- kids[tolower(f$type[kids]) %in% tt]\n    if (!length(iso)) iso <- kids\n    if (length(iso) < 2) next\n    subtrees <- lapply(iso, function(i) c(i, descendants(fid[i])))\n    size <- vapply(subtrees, coding_bp, numeric(1))\n    if (all(size == 0)) size <- f$end[iso] - f$start[iso]\n    winner <- max(which(size == max(size)))          # tie -> later isoform\n    drop <- c(drop, unlist(subtrees[-winner]))\n  }\n  if (length(drop)) f[-drop, , drop = FALSE] else f\n}",
  cram_to_bam: "# Rsamtools/GenomicAlignments is a BAM-only reader and cannot open CRAM, so\n# decode the queried region to a temporary indexed BAM with samtools (the\n# standard CRAM tool) and hand that back for the bam_* helpers to read. samtools\n# restores the MD tag from the reference while decoding, so the reference-free\n# bam_mismatches walk still works. 'ref' is the reference FASTA; when NULL/empty\n# samtools resolves the reference from the CRAM's own UR header or a\n# REF_PATH/REF_CACHE cache. A plain (non-.cram) path is returned unchanged, so\n# the same script works for BAM and CRAM tracks. Requires samtools on PATH.\ncram_to_bam <- function(uri, chrom, start, end, ref = NULL) {\n  if (!grepl(\"\\\\.cram$\", uri, ignore.case = TRUE)) return(uri)\n  out <- tempfile(fileext = \".bam\")\n  region <- sprintf(\"%s:%d-%d\", chrom, start + 1, end)\n  decode <- function(extra, env = character(0)) system2(\"samtools\",\n    c(\"view\", \"-b\", \"-o\", out, extra, uri, region), env = env) == 0\n  have_ref <- !is.null(ref) && nzchar(ref)\n  ok <- decode(if (have_ref) c(\"-T\", ref) else character(0))\n  if (!ok) {\n    # Two ways a perfectly readable CRAM fails here, and a public one usually\n    # hits both:\n    #\n    #  - given -T, samtools uses ONLY that fasta, so a reference whose contigs\n    #    are named differently from the CRAM header (\"1\" vs \"chr9\") fails. A\n    #    JBrowse assembly routinely pairs a no-prefix fasta with refname\n    #    aliases, and that fasta is where `ref` comes from.\n    #  - unaided, samtools resolves each sequence by MD5 - starting from the\n    #    CRAM's UR header, which for a published file is typically the\n    #    producer's own cluster path and long gone. Modern htslib does not fall\n    #    back to a remote lookup by itself.\n    #\n    # So retry unaided with the ENA md5 service as REF_PATH, htslib's documented\n    # recipe for precisely this. An existing REF_PATH (a local REF_CACHE, an\n    # offline mirror) is left alone.\n    message(\"samtools could not decode \", uri,\n            if (have_ref) paste0(\" against \", ref) else \"\",\n            \" - retrying by MD5 reference lookup\")\n    # That lookup returns a WHOLE reference sequence, so it is minutes per\n    # chromosome, and this helper runs once per panel per region - a coverage +\n    # pileup view of one CRAM region fetched the same ~200 Mb chromosome twice,\n    # and a multi-region view once more per region. REF_CACHE is htslib's own\n    # answer: it stores what it fetched and reuses it, so only the first call\n    # pays. Scoped to the R session's tempdir, which keeps a large download off\n    # the user's disk for good; point REF_CACHE at a persistent directory (or\n    # populate one with samtools' seq_cache_populate.pl) to keep it across runs.\n    cache <- Sys.getenv(\"REF_CACHE\")\n    if (!nzchar(cache)) {\n      dir.create(file.path(tempdir(), \"hts-ref\"), showWarnings = FALSE, recursive = TRUE)\n      cache <- file.path(tempdir(), \"hts-ref\", \"%2s\", \"%2s\", \"%s\")\n    }\n    ok <- decode(character(0), c(\n      if (nzchar(Sys.getenv(\"REF_PATH\"))) character(0)\n      else \"REF_PATH=https://www.ebi.ac.uk/ena/cram/md5/%s\",\n      paste0(\"REF_CACHE=\", cache)))\n  }\n  if (!ok) stop(\"samtools failed to decode CRAM: \", uri)\n  Rsamtools::indexBam(out)\n  out\n}",
  dendro_segments: "# Convert an hclust tree into geom_segment rows (rectangular elbows) for a\n# left-hand dendrogram panel. x = merge height (0 at leaves), y = leaf position\n# in hc$order, so the leaves line up 1:1 with a sample-by-site matrix whose rows\n# are ordered by the same hclust. Hand-rolled from hc$merge/height (base stats,\n# no ggdendro dependency), same spirit as the inline gene_layout helper.\ndendro_segments <- function(hc) {\n  merge <- hc$merge; height <- hc$height\n  n <- nrow(merge) + 1\n  leaf_y <- integer(n); leaf_y[hc$order] <- seq_len(n)\n  node_x <- numeric(nrow(merge)); node_y <- numeric(nrow(merge))\n  loc <- function(e) if (e < 0) c(0, leaf_y[-e]) else c(node_x[e], node_y[e])\n  segs <- vector(\"list\", nrow(merge))\n  for (k in seq_len(nrow(merge))) {\n    l <- loc(merge[k, 1]); r <- loc(merge[k, 2]); h <- height[k]\n    node_x[k] <- h; node_y[k] <- (l[2] + r[2]) / 2\n    segs[[k]] <- data.frame(\n      x = c(l[1], r[1], h), y = c(l[2], r[2], l[2]),\n      xend = c(h, h, h), yend = c(l[2], r[2], r[2]))\n  }\n  do.call(rbind, segs)\n}",
  feature_filter: "# JBrowse's feature admission, the gate between \"what the file holds\" and \"what\n# the track draws\" (featureAdmission.ts). Without it an R figure is not the same\n# picture as the browser: a default-configured feature track already hides the\n# NCBI whole-sequence source record (gbkey=Src), which spans an entire\n# chromosome, so an unfiltered export drew a bar across the whole width of every\n# NCBI gene panel that the browser never shows.\n#\n# 'preds' is a list of vectorized predicates - each takes the feature frame and\n# returns one logical per row - so a filter is ordinary R you can read, edit and\n# add to (`function(f) f$type != \"match\"`). 'types' (non-NULL only under \"Show\n# only genes\") is the allowed top-level type list, matched case-insensitively.\n#\n# Both gates apply to TOP-LEVEL features only, because JBrowse's does: admission\n# runs over the adapter's top-level features and takes each one's whole subtree\n# with it. Dropping a root here leaves its children with no root, and\n# gene_layout drops them for the same reason - so the subtree goes as a unit\n# without this having to walk it.\nfeature_filter <- function(f, preds = list(), types = NULL) {\n  if (!nrow(f)) return(f)\n  pass <- Reduce(`&`, lapply(preds, function(p) p(f)), rep(TRUE, nrow(f)))\n  if (!is.null(types)) pass <- pass & tolower(f$type) %in% tolower(types)\n  f[!is.na(f$parent) | pass, , drop = FALSE]\n}",
  gap_colors: "# JBrowse's CIGAR-gap colors: deletion grey, skip/intron teal, insertion purple.\n# A deletion paints a grey full-height rect over the read body; a spliced intron\n# erases the body and leaves a thin teal connector line; an insertion is a thin\n# purple tick marking sequence absent from the reference.\ngap_colors <- c(D = \"#808080\", N = \"#009a8a\", I = \"#800080\")",
  gene_layout: "# Group features under their top-level (parent-less) ancestor and row-pack the\n# ancestors with IRanges::disjointBins (the interval-stacking primitive).\ngene_layout <- function(f) {\n  f$fid <- ifelse(is.na(f$id), paste0(\"_f\", seq_len(nrow(f))), f$id)\n  parent <- setNames(f$parent, f$fid)\n  root_of <- function(id) {\n    p <- parent[[id]]\n    while (!is.na(p) && p %in% names(parent)) { id <- p; p <- parent[[id]] }\n    id\n  }\n  f$root <- vapply(f$fid, root_of, character(1))\n  roots <- f[is.na(f$parent), , drop = FALSE]\n  roots$row <- disjointBins(IRanges(roots$start + 1L, roots$end))\n  f$row <- setNames(roots$row, roots$fid)[f$root]\n  f[!is.na(f$row), , drop = FALSE]\n}",
  hic_regions: "# Read a Hi-C contact matrix (strawr - the reader from the .hic authors) over\n# every displayed region and rotate it 45 degrees into diamond polygons, so the\n# map shares the cumulative-bp x-axis with the other stacked tracks. This is\n# JBrowse's triangular Hi-C view.\n#\n# It reads every PAIR of regions, not each region against itself, which is what\n# a discontiguous view is for: the contacts BETWEEN two windows are the whole\n# point of putting them side by side (the same geometry that puts a bright\n# off-diagonal block over a translocation's partner loci), and a per-region read\n# draws two separate triangles with the block between them simply missing.\n#\n# straw returns each block's upper triangle as data.frame(x, y, counts) of\n# bin-start coords. A bin-bin square [x, x+binsize] x [y, y+binsize] becomes a\n# diamond whose axis x is the contact midpoint and whose height is the\n# interaction distance - taken on the CUMULATIVE axis, so a cross-region contact\n# lands over the gap between its two regions and rises by their separation on\n# screen rather than by their genomic distance.\n#\n# 'binsize' must be a resolution the file offers (strawr::readHicBpResolutions(\n# uri)) and 'norm' a normalization it offers (strawr::readHicNormTypes(uri)) -\n# both are editable script variables below (larger binsize = coarser/faster).\n# 'regions' must have been through region_layout() (it reads $offset).\nhic_regions <- function(uri, regions, binsize, norm) {\n  chroms <- strawr::readHicChroms(uri)\n  loc <- function(i) sprintf(\"%s:%d:%d\", regions$chrom[i], regions$start[i], regions$end[i])\n  # genomic bp -> the cumulative-bp axis position region i occupies\n  on_axis <- function(v, i) v + regions$offset[i] - regions$start[i]\n  # straw answers on the file's own axis order, transposing the block when the\n  # second locus sorts first, so x is not always region i's coordinate\n  transposed <- function(i, j) {\n    if (regions$chrom[i] == regions$chrom[j]) regions$start[i] > regions$start[j]\n    else match(regions$chrom[i], chroms$name) > match(regions$chrom[j], chroms$name)\n  }\n  block <- function(i, j) {\n    # a pair the file has no matrix for at this resolution contributes nothing\n    # rather than failing the figure: inter-chromosomal blocks commonly exist\n    # only at the coarser binsizes, and many .hic files have none at all\n    m <- tryCatch(strawr::straw(norm, uri, loc(i), loc(j), unit = \"BP\", binsize = binsize),\n                  error = function(e) NULL)\n    if (is.null(m) || !nrow(m)) return(NULL)\n    if (transposed(i, j)) m[c(\"x\", \"y\")] <- m[c(\"y\", \"x\")]\n    # the four corners of each bin-bin square, each end on its own region's axis\n    cx <- on_axis(c(m$x, m$x + binsize, m$x + binsize, m$x), i)\n    cy <- on_axis(c(m$y, m$y, m$y + binsize, m$y + binsize), j)\n    data.frame(gx = (cx + cy) / 2, gy = (cy - cx) / 2, counts = rep(m$counts, 4),\n               # one group per contact, per pair, so no two diamonds merge\n               group = paste(i, j, rep(seq_len(nrow(m)), 4), sep = \"-\"))\n  }\n  n <- nrow(regions)\n  ij <- subset(expand.grid(j = seq_len(n), i = seq_len(n)), i <= j)\n  do.call(rbind, Map(block, ij$i, ij$j))\n}",
  interbase_counts: "# JBrowse's coverage-band interbase counts: at each reference column, how many\n# reads have an insertion (bam_indels type \"I\") or a soft/hard clip (bam_clips\n# type \"S\"/\"H\") anchored at that interbase boundary. Mirrors the bucket pass of\n# computeInterbaseCoverage, and is the shared tally behind both marks JBrowse\n# draws from it - the stacked count histogram and, for the columns that clear\n# the significance gate, interbase_indicators().\n#\n# Returns one row per (column, event type) with a non-zero count, stacked in\n# JBrowse's order - insertion, then softclip, then hardclip - as the half-open\n# count range [ybase, ytop); a caller turns that range into a bar. 'total' is the\n# column's event count across all three types, repeated on each of its rows.\n# Empty frame when neither input has an event anywhere.\ninterbase_counts <- function(indels, clips) {\n  ins  <- if (is.null(indels)) integer(0) else indels$refpos[indels$type == \"I\"]\n  soft <- if (is.null(clips))  integer(0) else clips$pos[clips$type == \"S\"]\n  hard <- if (is.null(clips))  integer(0) else clips$pos[clips$type == \"H\"]\n  pos <- sort(unique(c(ins, soft, hard)))\n  if (!length(pos)) {\n    return(data.frame(pos = integer(0), type = character(0), count = integer(0),\n                      ybase = integer(0), ytop = integer(0), total = integer(0),\n                      stringsAsFactors = FALSE))\n  }\n  tally <- function(x) { v <- as.integer(table(x)[as.character(pos)]); v[is.na(v)] <- 0L; v }\n  counts <- list(I = tally(ins), S = tally(soft), H = tally(hard))\n  total <- counts$I + counts$S + counts$H\n  # stack in I, S, H order: each type's bar starts where the previous ones ended\n  ybase <- integer(length(pos))\n  out <- vector(\"list\", 3)\n  for (k in seq_along(counts)) {\n    n <- counts[[k]]\n    out[[k]] <- data.frame(pos = pos, type = names(counts)[k], count = n,\n                           ybase = ybase, ytop = ybase + n, total = total,\n                           stringsAsFactors = FALSE)\n    ybase <- ybase + n\n  }\n  out <- do.call(rbind, out)\n  out <- out[out$count > 0, , drop = FALSE]\n  out[order(out$pos, match(out$type, c(\"I\", \"S\", \"H\"))), , drop = FALSE]\n}",
  interbase_indicators: "# JBrowse's coverage-band interbase indicators: a marker above the interbase\n# count histogram where insertions / soft- or hard-clips pile up at one reference\n# column - a structural-variant breakpoint signal (mirrors\n# computeInterbaseCoverage). Takes the per-column tally the histogram is drawn\n# from and the coverage, and keeps only the columns where local depth >=\n# min_depth and the events exceed 'threshold' of it, typed by the dominant event.\n# Returns data.frame(pos, type in {I,S,H}, count); empty when nothing at any\n# column is significant.\ninterbase_indicators <- function(counts, cov, min_depth = 8, threshold = 0.3) {\n  if (is.null(counts) || !nrow(counts)) {\n    return(data.frame(pos = integer(0), type = character(0), count = integer(0),\n                      stringsAsFactors = FALSE))\n  }\n  # dominant type per column: the largest count, ties going to the earlier of\n  # insertion, softclip, hardclip - which is what computeInterbaseCoverage's\n  # stepwise \"> dominantCount\" comparison does, since only a strict majority\n  # upgrades the type\n  o <- order(counts$pos, -counts$count, match(counts$type, c(\"I\", \"S\", \"H\")))\n  top <- counts[o, , drop = FALSE]\n  top <- top[!duplicated(top$pos), , drop = FALSE]\n  # local depth at an INTERBASE position is the larger of the two bases it sits\n  # between (interbaseDepthAt), not the depth of the base to its right. The\n  # difference is the whole point at a breakpoint: every read's soft clip is\n  # anchored where the alignments stop, so the base to the right has depth 0 and\n  # the right-hand-only lookup gated out exactly the pileups this flags.\n  left  <- cov$depth[match(top$pos - 1, cov$pos)]; left[is.na(left)] <- 0\n  right <- cov$depth[match(top$pos, cov$pos)];     right[is.na(right)] <- 0\n  depth <- pmax(left, right)\n  keep <- depth >= min_depth & top$total > depth * threshold\n  data.frame(pos = top$pos[keep], type = top$type[keep], count = top$total[keep],\n             stringsAsFactors = FALSE)\n}",
  keep_rows: "# Drop a per-read overlay's rows for reads that \"Filter by\" rejected. An overlay\n# (bam_mismatches / bam_indels / bam_clips) carries a read_index = position in\n# readGAlignments order, so read_filter's 'keep' logical lines up 1:1 and\n# keep[df$read_index] selects the surviving rows.\n#\n# Only safe where the overlay is consumed on its own - the coverage panel, which\n# just counts rows. Do NOT use this on the pileup's overlays: those join back to\n# a row via reads$row[x$read_index], and dropping rows renumbers read_index and\n# desyncs the join. The pileup instead leaves a filtered read at an NA row, and\n# ggplot omits its body and ticks for free.\nkeep_rows <- function(df, keep) {\n  if (is.null(df) || !nrow(df)) return(df)\n  df[keep[df$read_index], , drop = FALSE]\n}",
  label_room: "# Which top-level features keep their name, the R counterpart of JBrowse's\n# `fitWidth` label decimation: a name is drawn only where there is room for it,\n# and dropped where it would collide with the next name on the same packed row.\n# Without this the panel labels every feature, and a dense track (a 2.5 Mb window\n# of DGV structural variants, say) comes out as a wall of overlapping text where\n# the browser draws bare glyphs.\n#\n# The panel centres each name on its feature, so two names on a row collide when\n# the distance between their centres is less than their combined half-widths -\n# which is why this is not simply \"is the feature box wide enough\": a set of long\n# features stacked across the same window have their centres almost on top of\n# each other however wide each box is, and that is exactly the case that used to\n# look worst.\n#\n# Text width has to be estimated, because a ggplot lives in data space and only\n# the device knows how wide a character is: `width_px` is the figure's plotting\n# width in pixels (the emitted ggsave() width x dpi, less the axis) and\n# `char_px` the average glyph width at the panel's label size. Both are ordinary\n# arguments - raise width_px if you ggsave() bigger and want the names back.\nlabel_room <- function(d, regions, width_px = 1730, char_px = 7.5) {\n  keep <- rep(FALSE, nrow(d))\n  roots <- which(is.na(d$parent) & !is.na(d$name))\n  if (!length(roots)) return(keep)\n  # the drawn axis, gaps between regions included, since that is what width_px\n  # spans; falls back to the bare region widths if region_layout hasn't run\n  span <- if (is.null(regions$cum_end)) sum(regions$end - regions$start)\n          else max(regions$cum_end) - min(regions$cum_start)\n  bp_per_px <- span / width_px\n  for (row_ids in split(roots, d$row[roots])) {\n    mid <- (d$start[row_ids] + d$end[row_ids]) / 2\n    o <- row_ids[order(mid)]\n    w <- nchar(d$name[o]) * char_px * bp_per_px\n    # the last name on a row has the rest of the axis to spill into\n    keep[o] <- c(diff(sort(mid)), Inf) >= (w + c(w[-1], 0)) / 2\n  }\n  keep\n}",
  link_reads: "# Chain layout (JBrowse's linkedReads = \"normal\"): group a region's records by\n# read name (QNAME) - the two mates of a pair plus any supplementary/secondary\n# segments share one name - and place each whole chain on a single row, packing\n# chains by their min-start..max-end span with disjointBins (the same primitive\n# pileup_layout uses on individual reads). Reads keep their original read_bam\n# order (only a 'row' column is added) so mismatch/mod ticks still join by\n# read_index. Also returns a 'links' data.frame of connector segments spanning the\n# gap between each chain's consecutive pieces (the mate-pair gap or split-read\n# junction). A record whose mate/other segment falls outside the fetched window\n# simply has no connector (only the segments actually in view are linked).\nlink_reads <- function(reads) {\n  keep <- if (is.null(reads$keep)) rep(TRUE, nrow(reads)) else reads$keep\n  k <- which(keep); sub <- reads[k, ]\n  nm <- ifelse(is.na(sub$name), paste0(\"_r\", k), sub$name)\n  chain_start <- tapply(sub$start, nm, min)\n  chain_end   <- tapply(sub$end, nm, max)\n  crow <- disjointBins(IRanges(as.integer(chain_start) + 1L, as.integer(chain_end)))\n  names(crow) <- names(chain_start)\n  row <- rep(NA_integer_, nrow(reads))\n  row[k] <- unname(crow[nm])\n  reads$row <- row\n  ord <- order(nm, sub$start); s <- sub[ord, ]; g <- nm[ord]\n  same <- g[-1] == g[-length(g)]\n  x0 <- s$end[-nrow(s)]; x1 <- s$start[-1]; keeplink <- same & x1 > x0\n  links <- data.frame(xstart = x0[keeplink], xend = x1[keeplink], row = row[k][ord][-1][keeplink])\n  list(reads = reads, links = links)\n}",
  mismatch_fade_alpha: "# JBrowse's low-frequency mismatch fade, per tick: frequencyFade over\n# computeMismatchFrequencies + the depth threshold. Zoomed in (<= 1 bp/px) every\n# tick is opaque (1). Zoomed out, alpha = pxPerBp lifted toward 1 by the base's\n# frequency (reads with that base at the column / depth, rounded to a 0-255 byte\n# like the shader), and a base whose byte-frequency is below snp_freq_threshold(\n# depth) is held at the faint pxPerBp noise floor. 'depth' is a bam_coverage()\n# data.frame(pos, depth). Returns an alpha vector aligned to refpos/base.\nmismatch_fade_alpha <- function(refpos, base, depth, bp_per_px) {\n  n <- length(refpos)\n  if (bp_per_px <= 1) return(rep(1, n))\n  base_alpha <- 1 / bp_per_px\n  count <- ave(refpos, refpos, base, FUN = length)     # reads with this base here\n  d <- depth$depth[match(refpos, depth$pos)]\n  freq <- ifelse(!is.na(d) & d > 0, count / d, 0)\n  fb <- pmin(255L, as.integer(round(freq * 255)))      # frequency as a 0-255 byte\n  thr <- snp_freq_threshold(d)\n  fb[!is.na(thr) & (fb / 255) < thr] <- 0L             # below threshold -> noise floor\n  base_alpha + (fb / 255) * (1 - base_alpha)\n}",
  mod_colors: "# Base-modification type colors (IGV/JBrowse palette: red 5mC 'm', magenta 5hmC\n# 'h', deep-blue 6mA 'a', ...). Codes outside the table hash to a stable muted\n# hue, mirroring JBrowse's randomColor fallback. Returned as literal hex so mod\n# ticks share one scale_fill_identity() with the read bodies.\nmod_colors <- function(types) {\n  pal <- c(m = \"#ff0000\", h = \"#ff00ff\", o = \"#6f4e81\", f = \"#f6c85f\",\n           c = \"#9dd866\", g = \"#ffa056\", e = \"#8dddd0\", b = \"#00642f\",\n           a = \"#33006f\", \"17082\" = \"#3399ff\", \"17596\" = \"#669900\",\n           \"21839\" = \"#990099\")\n  hsl <- function(h, s, l) {\n    cc <- (1 - abs(2 * l - 1)) * s; x <- cc * (1 - abs((h / 60) %% 2 - 1)); m <- l - cc / 2\n    rgbv <- switch(floor(h / 60) %% 6 + 1, c(cc, x, 0), c(x, cc, 0), c(0, cc, x),\n                   c(0, x, cc), c(x, 0, cc), c(cc, 0, x))\n    grDevices::rgb(rgbv[1] + m, rgbv[2] + m, rgbv[3] + m)\n  }\n  vapply(as.character(types), function(t)\n    if (!is.na(pal[t])) unname(pal[t]) else hsl((sum(utf8ToInt(t)) * 10) %% 360, 0.2, 0.5),\n    character(1), USE.NAMES = FALSE)\n}",
  mod_coverage: "# JBrowse's coverage-band modification counts: at each column, what share of the\n# depth bar each modification type takes. Mirrors computeModificationCoverage,\n# which is IGV's BaseModificationCoverageRenderer:\n#\n#   height = (modifiable / depth) * (calls / detectable)\n#\n# 'modifiable' is the reads that even carry the base the mod sits on - a 5mC sits\n# on a C, and the same cytosine read from the other strand is a G, so both count.\n# 'detectable' narrows that to the reads actually examined: for a simplex mod\n# (see mod_simplex_types) that is the base on forward reads plus its complement on\n# reverse reads, and dividing by the full 'modifiable' there would halve every\n# bar. Duplex mods have detectable == modifiable, collapsing the height to\n# calls/depth. The height is a read COUNT - each qualifying read weighs 1\n# regardless of how confident its call was; likelihood feeds only the alpha.\n#\n# 'mods' is bam_modifications' frame, already threshold-filtered, so a call below\n# min_prob is simply absent - the same way JBrowse's extraction drops it before\n# the coverage pass ever sees it. 'counts' is read_base_counts, 'cov' is\n# bam_coverage. Types stack bottom-up in JBrowse's fixed rank order so a column's\n# segments can't swap between draws, and each bin carries the mean call\n# likelihood for the panel to bake into the segment's alpha.\n#\n# Returns data.frame(pos, modtype, ybase, ytop, prob, depth), where ybase/ytop are\n# fractions of that column's own depth bar. Empty frame when nothing is drawable.\nmod_coverage <- function(mods, counts, cov, simplex = character(0)) {\n  empty <- data.frame(pos = integer(0), modtype = character(0), ybase = numeric(0),\n                      ytop = numeric(0), prob = numeric(0), depth = numeric(0),\n                      stringsAsFactors = FALSE)\n  if (is.null(mods) || !nrow(mods) || is.null(counts) || !nrow(counts)) return(empty)\n  # one bin per (column, type): how many reads called it, and how confidently\n  n <- aggregate(prob ~ refpos + modtype + base, data = mods, FUN = length)\n  names(n)[names(n) == \"prob\"] <- \"calls\"\n  m <- aggregate(prob ~ refpos + modtype + base, data = mods, FUN = mean)\n  bins <- merge(n, m, by = c(\"refpos\", \"modtype\", \"base\"))\n  bins$depth <- cov$depth[match(bins$refpos, cov$pos)]\n  bins <- bins[!is.na(bins$depth) & bins$depth > 0, , drop = FALSE]\n  if (!nrow(bins)) return(empty)\n  key <- paste(counts$pos, counts$base)\n  at <- function(pos, base, col) {\n    v <- counts[[col]][match(paste(pos, base), key)]; v[is.na(v)] <- 0L; v\n  }\n  compl <- c(A = \"T\", T = \"A\", C = \"G\", G = \"C\", U = \"A\", N = \"N\")\n  b <- toupper(bins$base); cb <- unname(compl[b]); cb[is.na(cb)] <- \"N\"\n  bf <- at(bins$refpos, b, \"fwd\"); br <- at(bins$refpos, b, \"rev\")\n  cf <- at(bins$refpos, cb, \"fwd\"); cr <- at(bins$refpos, cb, \"rev\")\n  modifiable <- bf + br + cf + cr\n  detectable <- ifelse(bins$modtype %in% simplex, bf + cr, modifiable)\n  # base \"N\" means the mod can sit on any read, so both counts are the column's\n  # whole read-base total\n  isN <- b == \"N\"\n  if (any(isN)) {\n    tot <- tapply(counts$fwd + counts$rev, counts$pos, sum)\n    tv <- as.numeric(tot[as.character(bins$refpos)]); tv[is.na(tv)] <- 0\n    modifiable[isN] <- tv[isN]; detectable[isN] <- tv[isN]\n  }\n  h <- ifelse(detectable == 0, 0, (modifiable / bins$depth) * (bins$calls / detectable))\n  # fixed stack order (JBrowse's MOD_TYPE_RANK, from IGV's modificationRankOrder),\n  # with the type name breaking ties so numeric ChEBI codes - which all share the\n  # fallback rank - are ordered too\n  type_rank <- c(m = 0, h = 1, f = 2, c = 3, C = 4, g = 5, e = 6, b = 7, a = 8, o = 9)\n  r <- unname(type_rank[bins$modtype]); r[is.na(r)] <- 99\n  o <- order(bins$refpos, r, bins$modtype)\n  bins <- bins[o, , drop = FALSE]; h <- h[o]\n  drawn <- h > 0\n  bins <- bins[drawn, , drop = FALSE]; h <- h[drawn]\n  if (!nrow(bins)) return(empty)\n  ytop <- ave(h, bins$refpos, FUN = cumsum)\n  data.frame(pos = bins$refpos, modtype = bins$modtype, ybase = ytop - h,\n             ytop = ytop, prob = bins$prob, depth = bins$depth,\n             stringsAsFactors = FALSE)\n}",
  mod_simplex_types: "# Which modification types were basecalled on only ONE strand (\"simplex\"). The MM\n# tag names each group's strand: \"C+m\" is 5mC on the read's own strand, \"C-m\" the\n# same cytosine read from the other side. A type seen on '+' with no '-' partner\n# anywhere was examined on one strand only, and mod_coverage must then divide by\n# the reads on that strand alone - dividing by every read carrying the base would\n# halve each bar, since half of them could never have shown the call.\n#\n# Takes the \"<sign><type>\" pairs bam_modifications hangs on its result as the\n# \"mm_strands\" attribute, pooled over every region: simplex-ness is a property of\n# the protocol, not of a read or a window, and a single read can lack the '-' call\n# just by covering no eligible base. Mirrors detectSimplexModifications.\nmod_simplex_types <- function(pairs) {\n  pairs <- unique(pairs[!is.na(pairs)])\n  if (!length(pairs)) return(character(0))\n  mmsign <- substr(pairs, 1, 1); type <- substring(pairs, 2)\n  setdiff(unique(type[mmsign == \"+\"]), unique(type[mmsign == \"-\"]))\n}",
  open_reference: "# A reference sequence handle for whichever format the assembly stores it in.\n# Both answer getSeq(handle, GRanges) the same way, so callers need not care.\n# An indexed FASTA wants its .fai beside it; a 2bit carries its own index.\nopen_reference <- function(path) {\n  if (grepl(\"\\\\.2bit$\", path, ignore.case = TRUE)) {\n    rtracklayer::TwoBitFile(path)\n  } else {\n    FaFile(path)\n  }\n}",
  pair_orientation: "# Classify a read pair's orientation into the IGV FR-library categories\n# (LR normal / RL / RR / LL), reproducing JBrowse's getPairOrientation +\n# pairDirection. Vectorized over a BAM's flag / position columns. The leftmost\n# mate (self_left) is chosen consistently from either read - by position within a\n# chromosome, read1-first when positions tie or the mate position is unknown - so\n# the two mates of one pair always agree. Returns NA for unpaired reads or\n# orientations outside the FR set. self_pos/mate_pos are 1-based leftmost coords.\npair_orientation <- function(flag, self_pos, mate_pos) {\n  is_paired <- bitwAnd(flag, 0x1L) != 0\n  is_read1  <- bitwAnd(flag, 0x40L) != 0\n  self_str  <- ifelse(bitwAnd(flag, 0x10L) != 0, \"R\", \"F\")\n  mate_str  <- ifelse(bitwAnd(flag, 0x20L) != 0, \"R\", \"F\")\n  self_num  <- ifelse(is_read1, \"1\", \"2\")\n  mate_num  <- ifelse(is_read1, \"2\", \"1\")\n  known     <- !is.na(mate_pos) & mate_pos > 0\n  self_left <- ifelse(!known | self_pos == mate_pos, is_read1, self_pos < mate_pos)\n  o <- ifelse(self_left,\n    paste0(self_str, self_num, mate_str, mate_num),\n    paste0(mate_str, mate_num, self_str, self_num))\n  fr <- c(F1R2 = \"LR\", F2R1 = \"LR\", R1F2 = \"RL\", R2F1 = \"RL\",\n          R1R2 = \"RR\", R2R1 = \"RR\", F1F2 = \"LL\", F2F1 = \"LL\")\n  ifelse(is_paired, unname(fr[o]), NA_character_)\n}",
  pileup_layout: "# Stack overlapping reads into rows. IRanges::disjointBins is the standard\n# interval-stacking primitive - the same idea as the JBrowse pileup layout. A\n# 'keep' column (from read_filter) leaves filtered reads at an NA row (undrawn).\npileup_layout <- function(reads) {\n  keep <- if (is.null(reads$keep)) rep(TRUE, nrow(reads)) else reads$keep\n  row <- rep(NA_integer_, nrow(reads))\n  row[keep] <- disjointBins(IRanges(reads$start[keep] + 1L, reads$end[keep]))\n  reads$row <- row\n  reads\n}",
  quality_colors: "# JBrowse's per-base-quality color ramp: each Phred score maps to HSL(hue, 55%,\n# 50%) with hue = score * 1.5 (red at low quality -> yellow -> green at high), a\n# maxed score pinned to green hue 150. Vectorized; HSL is converted to hex inline\n# because base R has no HSL constructor (hsv() is a different color space).\nquality_colors <- function(scores) {\n  h <- ifelse(scores >= 255, 150, scores * 1.5)\n  s <- 0.55; l <- 0.5\n  cc <- (1 - abs(2 * l - 1)) * s\n  x <- cc * (1 - abs((h / 60) %% 2 - 1))\n  m <- l - cc / 2\n  r <- g <- b <- numeric(length(h))\n  i <- h < 60;             r[i] <- cc;   g[i] <- x[i]\n  i <- h >= 60  & h < 120; r[i] <- x[i]; g[i] <- cc\n  i <- h >= 120 & h < 180; g[i] <- cc;   b[i] <- x[i]\n  i <- h >= 180 & h < 240; g[i] <- x[i]; b[i] <- cc\n  i <- h >= 240 & h < 300; r[i] <- x[i]; b[i] <- cc\n  i <- h >= 300;           r[i] <- cc;   b[i] <- x[i]\n  rgb(r + m, g + m, b + m)\n}",
  read_bam: "# Read alignments in a region as a data.frame(name, start, end, strand, mapq,\n# isize, flag, orientation, mate_unmapped, interchrom), with reference-based\n# (CIGAR-aware) coordinates. isize is |TLEN| (0 for unpaired) so a\n# color-by-insert-size panel works without a reference; orientation / mate_unmapped\n# / interchrom drive the pair-orientation coloring (see pair_orientation); name is\n# QNAME, so mates + supplementary segments can be grouped into chains (link_reads).\nread_bam <- function(uri, chrom, start, end) {\n  ga <- readGAlignments(uri, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end)),\n    what = c(\"qname\", \"flag\", \"mapq\", \"isize\", \"mrnm\", \"mpos\")))\n  flag <- mcols(ga)$flag\n  mate_chrom <- as.character(mcols(ga)$mrnm)\n  data.frame(name = mcols(ga)$qname, start = start(ga) - 1L, end = end(ga),\n             strand = as.character(strand(ga)), mapq = mcols(ga)$mapq,\n             isize = abs(mcols(ga)$isize), flag = flag,\n             orientation = pair_orientation(flag, start(ga), mcols(ga)$mpos),\n             mate_unmapped = bitwAnd(flag, 0x8L) != 0,\n             # \"=\" is RNEXT shorthand for the read's own chromosome\n             interchrom = !is.na(mate_chrom) & mate_chrom != chrom & mate_chrom != \"=\",\n             stringsAsFactors = FALSE)\n}",
  read_base_counts: "# Per-strand read-base counts at a set of reference columns - the denominator\n# JBrowse's modification coverage divides by (computeReadBaseCounts, itself IGV's\n# DenseAlignmentCounts). Reference-free: it reads each read's own SEQ, so a\n# modBAM still needs no FASTA here.\n#\n# Restricted to 'positions' (the modified columns) so it costs one CIGAR walk per\n# read but tallies only where a modification was actually called, rather than\n# building a region-wide pileup. Only M/=/X columns carry a base, which is the\n# gate JBrowse's walk uses too - a deleted column is covered by no read's base and\n# so must not enter the denominator.\n#\n# 'keep' is read_filter's logical in readGAlignments order, so the counts come\n# from exactly the reads the panel draws.\n# Returns data.frame(pos [0-based], base, fwd, rev); NULL when nothing is covered.\nread_base_counts <- function(uri, chrom, start, end, positions, keep = NULL) {\n  want <- unique(as.integer(positions))\n  if (!length(want)) return(NULL)\n  ga <- readGAlignments(uri, param = ScanBamParam(\n    which = GRanges(chrom, IRanges(start + 1, end)), what = \"seq\"))\n  if (!is.null(keep)) ga <- ga[keep]\n  if (!length(ga)) return(NULL)\n  seqs <- as.character(mcols(ga)$seq); cig <- cigar(ga)\n  refstart <- start(ga); fwd <- as.character(strand(ga)) != \"-\"\n  out <- vector(\"list\", length(ga))\n  for (i in seq_along(ga)) {\n    s <- strsplit(seqs[i], \"\", fixed = TRUE)[[1]]; n <- length(s)\n    if (!n) next\n    # CIGAR read(1-based)->ref(1-based) column map, as in bam_modifications\n    ops <- regmatches(cig[i], gregexpr(\"[0-9]+[MIDNSHP=X]\", cig[i]))[[1]]\n    oplen <- as.integer(sub(\"[MIDNSHP=X]$\", \"\", ops)); opchr <- sub(\"^[0-9]+\", \"\", ops)\n    ref2 <- rep(NA_integer_, n); rp <- refstart[i]; qp <- 1L\n    for (k in seq_along(ops)) {\n      op <- opchr[k]; L <- oplen[k]\n      if (op %in% c(\"M\", \"=\", \"X\")) {\n        ref2[qp:(qp + L - 1L)] <- rp:(rp + L - 1L); rp <- rp + L; qp <- qp + L\n      } else if (op %in% c(\"I\", \"S\")) { qp <- qp + L\n      } else if (op %in% c(\"D\", \"N\")) { rp <- rp + L }\n    }\n    sel <- which(!is.na(ref2) & (ref2 - 1L) %in% want)\n    if (length(sel)) out[[i]] <- data.frame(\n      pos = ref2[sel] - 1L, base = toupper(s[sel]), fwdn = as.integer(fwd[i]),\n      stringsAsFactors = FALSE)\n  }\n  df <- do.call(rbind, out)\n  if (is.null(df) || !nrow(df)) return(NULL)\n  df$revn <- 1L - df$fwdn\n  agg <- aggregate(cbind(fwdn, revn) ~ pos + base, data = df, FUN = sum)\n  names(agg)[names(agg) == \"fwdn\"] <- \"fwd\"\n  names(agg)[names(agg) == \"revn\"] <- \"rev\"\n  agg\n}",
  read_bed: "# Read BED features in a region into the same schema read_gff returns\n# (start, end, strand, type, id, parent, name), so gene_layout and the gene\n# panel treat BED and GFF alike. A BED12 record is expanded into a transcript\n# root plus 'exon' subfeatures (its blocks) and 'CDS' subfeatures (each exon\n# clipped to the thickStart/thickEnd coding range) - the same thin-exon /\n# thick-CDS gene model a GFF gives. A plain BED (no block columns) yields one\n# flat 'feature' per record. start is 0-based half-open (BED-style). rtracklayer\n# returns block ranges relative to the feature start and thick as absolute\n# 1-based coords; a zero-width thick range means non-coding (no CDS drawn).\n# 'attrs' matches read_gff's signature so the gene panel can call either reader\n# the same way; BED carries no GFF attributes, so each becomes an all-NA column\n# (the jexl `undefined` case feature_filter() already handles).\n# format = \"bigBed\" reads the same schema out of an indexed .bb instead.\nread_bed <- function(uri, chrom, start, end, attrs = character(0),\n                     format = c(\"bed\", \"bigBed\")) {\n  # NULL when the region held no features, which read_regions already treats as\n  # \"contributed nothing\"; adding a column to it would build a bare list instead\n  with_attrs <- function(df) {\n    if (is.null(df)) return(NULL)\n    for (a in attrs) df[[a]] <- rep(NA_character_, nrow(df))\n    df\n  }\n  gr <- GRanges(chrom, IRanges(start + 1, end))\n  g <- if (match.arg(format) == \"bigBed\") {\n    # Name the fields we draw rather than take the whole record: a BigBed's\n    # extra autoSql columns are read through the UCSC C library, and an itemRgb\n    # spelled \"0,0,200\" fails as a signed integer - which aborts the WHOLE\n    # import with \"UCSC library operation failed\", so every `bigBed 9 +` track\n    # (UCSC's SV, ClinVar and repeat tracks are all one) was unreadable.\n    # A file without blocks/thick just warns here; the flat-feature path below\n    # is what it needs anyway.\n    withCallingHandlers(\n      import(uri, selection = BigBedSelection(gr,\n        colnames = c(\"name\", \"score\", \"thick\", \"blocks\"))),\n      warning = function(w)\n        if (grepl(\"Unavailable field\", conditionMessage(w))) invokeRestart(\"muffleWarning\"))\n  } else import(uri, which = gr, format = \"bed\")\n  m <- mcols(g)\n  nm <- if (is.null(m$name)) paste0(\"bed\", seq_along(g)) else as.character(m$name)\n  fs <- start(g); fe <- end(g); str <- as.character(strand(g))\n  flat <- function(i) data.frame(start = fs[i] - 1L, end = fe[i], strand = str[i],\n    type = \"feature\", id = nm[i], parent = NA_character_, name = nm[i],\n    stringsAsFactors = FALSE)\n  if (is.null(m$blocks)) return(with_attrs(do.call(rbind, lapply(seq_along(g), flat))))\n  out <- vector(\"list\", length(g))\n  for (i in seq_along(g)) {\n    bl <- m$blocks[[i]]\n    if (!length(bl)) { out[[i]] <- flat(i); next }\n    ex_s <- fs[i] + start(bl) - 1L; ex_e <- fs[i] + end(bl) - 1L\n    parts <- list(\n      data.frame(start = fs[i] - 1L, end = fe[i], strand = str[i], type = \"mRNA\",\n        id = nm[i], parent = NA_character_, name = nm[i], stringsAsFactors = FALSE),\n      data.frame(start = ex_s - 1L, end = ex_e, strand = str[i], type = \"exon\",\n        id = paste0(nm[i], \".exon\", seq_along(bl)), parent = nm[i],\n        name = NA_character_, stringsAsFactors = FALSE))\n    if (!is.null(m$thick) && end(m$thick)[i] > start(m$thick)[i]) {\n      ts <- start(m$thick)[i]; te <- end(m$thick)[i]\n      cs <- pmax(ex_s, ts); ce <- pmin(ex_e, te); keep <- cs <= ce\n      if (any(keep)) parts[[3]] <- data.frame(start = cs[keep] - 1L, end = ce[keep],\n        strand = str[i], type = \"CDS\", id = paste0(nm[i], \".cds\", which(keep)),\n        parent = nm[i], name = NA_character_, stringsAsFactors = FALSE)\n    }\n    out[[i]] <- do.call(rbind, parts)\n  }\n  with_attrs(do.call(rbind, out))\n}",
  read_bigwig: "# Read a BigWig region into a data.frame(seqnames, start, end, score). start is\n# 0-based half-open (BED-style), like every other reader here - rtracklayer hands\n# back 1-based inclusive GRanges coordinates, so the start is shifted back by one.\n# That conversion is what makes adjacent bins ABUT: a bigwig's bins tile the\n# genome, and left as 1-based each bar was drawn one bp right of its true span\n# with a 1bp hole against its neighbour. Sub-pixel at any normal zoom, but the\n# device antialiases each rect separately, so the holes beat against the pixel\n# grid and surfaced as scattered full-height white seams through a solid xyplot.\nread_bigwig <- function(uri, chrom, start, end) {\n  df <- as.data.frame(rtracklayer::import(uri, which = GRanges(chrom, IRanges(start + 1, end))))\n  df$start <- df$start - 1L\n  df\n}",
  read_fill_colors: "# Per-read body fill for a color-by scheme, returned as literal hex so read\n# bodies share one scale_fill_identity() with the mismatch ticks. Mirrors\n# JBrowse's read color schemes: normal (grey, the default), strand (pink fwd /\n# blue rev), mappingQuality (a fixed-saturation hue ramp over MAPQ, treating\n# MAPQ as a hue in degrees like the GPU renderer), insertSize (pink short / red\n# long / grey normal, thresholds = a robust median +/- 3*1.4826*MAD over the\n# primary proper-pair |TLEN| values, matching getInsertSizeStats),\n# pairOrientation (grey LR / teal RL / blue RR / green LL, with an unmapped-mate\n# and an inter-chromosomal bucket that override the orientation hue like JBrowse).\nread_fill_colors <- function(reads, color_by = \"normal\") {\n  hue_ramp <- function(h) {\n    hp <- (h %% 360) / 60; cc <- 0.5; mm <- 0.25\n    x <- cc * (1 - abs(hp %% 2 - 1))\n    r <- ifelse(hp < 1, cc, ifelse(hp < 2, x, ifelse(hp < 4, 0, ifelse(hp < 5, x, cc))))\n    g <- ifelse(hp < 1, x, ifelse(hp < 3, cc, ifelse(hp < 4, x, 0)))\n    b <- ifelse(hp < 2, 0, ifelse(hp < 3, x, ifelse(hp < 5, cc, x)))\n    grDevices::rgb(r + mm, g + mm, b + mm)\n  }\n  if (color_by == \"strand\") {\n    ifelse(reads$strand == \"-\", \"#8F8FD8\", \"#EC8B8B\")\n  } else if (color_by == \"mappingQuality\") {\n    hue_ramp(reads$mapq)\n  } else if (color_by == \"insertSize\") {\n    # JBrowse derives the short/long thresholds from primary proper-pair reads\n    # only (SAM flag 0x2 set, 0x100/0x800 clear) with |TLEN| > 0, using a robust\n    # spread: median +/- 3*1.4826*MAD, falling back to mean +/- 3*sd when MAD is 0,\n    # lower bound clamped at 0. The MAD ignores the right-skewed SV tail that would\n    # otherwise inflate sd and drive the lower bound negative, hiding every short\n    # insert. sd is population (divide by n) to match getInsertSizeStats. A read\n    # with |TLEN| == 0 (unpaired) is always \"normal\", never \"short\".\n    is <- reads$isize\n    proper <- bitwAnd(reads$flag, 0x2L) != 0 &\n              bitwAnd(reads$flag, 0x100L) == 0 & bitwAnd(reads$flag, 0x800L) == 0\n    obs <- is[proper & is > 0]\n    if (length(obs)) {\n      avg <- mean(obs); med <- median(obs); md <- median(abs(obs - med))\n      s <- if (length(obs) > 1) sqrt(sum((obs - avg)^2) / length(obs)) else 0\n      center <- if (md > 0) med else avg\n      spread <- if (md > 0) 3 * 1.4826 * md else 3 * s\n      upper <- center + spread; lower <- max(0, center - spread)\n    } else { upper <- Inf; lower <- 0 }\n    ifelse(is > upper, \"#ff0000\", ifelse(is > 0 & is < lower, \"#ffc0cb\", \"#d3d3d3\"))\n  } else if (color_by == \"pairOrientation\") {\n    pal <- c(LR = \"#d3d3d3\", RL = \"#0099bb\", RR = \"#5555bb\", LL = \"#4d9a4d\")\n    col <- unname(pal[reads$orientation])\n    col[is.na(col)] <- \"#c8c8c8\"                # unpaired / non-FR orientation\n    col[reads$interchrom] <- \"#6e4b3a\"          # mate on another chromosome\n    col[reads$mate_unmapped] <- \"#b05a20\"       # unmapped mate wins (like JBrowse)\n    col\n  } else {\n    rep(\"#d3d3d3\", nrow(reads))\n  }\n}",
  read_filter: "# Apply JBrowse's \"Filter by\" to the reads: SAM flag include/exclude, an optional\n# read-name match, and tag filters (all AND-ed; a value of \"*\" means \"has the\n# tag\"). Marks a logical 'keep' column rather than dropping rows, so read_index\n# still lines up with the mismatch/mod/clip overlays - the layout then gives a\n# filtered read an NA row and ggplot drops its body and ticks. Mirrors JBrowse's\n# filterReadFlag / filterTagValue. flag_exclude default 1540 = unmapped + QC-fail +\n# duplicate. Tag values are read only when a tag filter is set (an extra scan).\nread_filter <- function(reads, uri, chrom, start, end, flag_include = 0,\n                        flag_exclude = 1540, read_name = NULL, tag_filters = list()) {\n  keep <- bitwAnd(reads$flag, flag_include) == flag_include &\n          bitwAnd(reads$flag, flag_exclude) == 0\n  if (!is.null(read_name)) keep <- keep & !is.na(reads$name) & reads$name == read_name\n  if (length(tag_filters)) {\n    tags <- unique(vapply(tag_filters, function(f) f$tag, character(1)))\n    tv <- mcols(readGAlignments(uri, param = ScanBamParam(\n      which = GRanges(chrom, IRanges(start + 1, end)), tag = tags)))\n    for (f in tag_filters) {\n      val <- tv[[f$tag]]; has <- !is.na(val)\n      keep <- keep & (if (identical(f$value, \"*\")) has else has & as.character(val) == f$value)\n    }\n  }\n  reads$keep <- keep\n  reads\n}",
  read_gff: "# Read GFF3 features in a region into a\n# data.frame(start, end, strand, type, id, parent, name), plus one column per\n# name in 'attrs' - the extra GFF attributes the track's feature filters read\n# (e.g. gbkey for the NCBI source-record filter every track carries by default).\n# An attribute the file does not have becomes an all-NA column, which is the\n# jexl `undefined` feature_filter() already handles.\nread_gff <- function(uri, chrom, start, end, attrs = character(0)) {\n  g <- import(uri, which = GRanges(chrom, IRanges(start + 1, end)), format = \"gff\")\n  m <- mcols(g)\n  # length(g), not a bare NA: recycling a length-1 NA works only when there is\n  # at least one feature, so an empty region over a file lacking the attribute\n  # died on \"arguments imply differing number of rows: 0, 1\"\n  col <- function(nm) if (is.null(m[[nm]])) rep(NA_character_, length(g)) else as.character(m[[nm]])\n  parent <- if (is.null(m$Parent)) rep(NA_character_, length(g)) else\n    vapply(m$Parent, function(v) if (length(v)) as.character(v[[1]]) else NA_character_, character(1))\n  df <- data.frame(start = start(g) - 1L, end = end(g), strand = as.character(strand(g)),\n             type = col(\"type\"), id = col(\"ID\"), parent = parent, name = col(\"Name\"),\n             stringsAsFactors = FALSE)\n  for (a in attrs) df[[a]] <- col(a)\n  df\n}",
  read_gwas: "# Read GWAS association points from a tabix'd BED into data.frame(pos, score).\n# The score column is looked up by NAME in the header line (BedTabixAdapter's\n# scoreColumn, e.g. neg_log_pvalue); the genomic position column comes from the\n# tabix index (headerTabix()$indexColumns) so it works whatever BED layout the\n# file uses. pos is 0-based (BED chromStart). Rsamtools only - no GWAS package.\nread_gwas <- function(uri, chrom, start, end, score_col) {\n  tf <- TabixFile(uri)\n  h <- headerTabix(tf)\n  cols <- if (length(h$header))\n    strsplit(sub(\"^#\", \"\", h$header[length(h$header)]), \"\\t\", fixed = TRUE)[[1]]\n    else character(0)\n  score_i <- match(score_col, cols)\n  pos_col <- h$indexColumns[[\"start\"]]\n  lines <- unlist(scanTabix(tf, param = GRanges(chrom, IRanges(start + 1, end))))\n  if (!length(lines) || is.na(score_i)) {\n    return(data.frame(pos = integer(), score = numeric()))\n  }\n  m <- do.call(rbind, strsplit(lines, \"\\t\", fixed = TRUE))\n  data.frame(pos = as.integer(m[, pos_col]),\n             score = suppressWarnings(as.numeric(m[, score_i])))\n}",
  read_multibigwig: "# Read several BigWig files into one long data.frame with a 'source' column\n# (a factor ordered to match 'names'), reusing read_bigwig per file.\nread_multibigwig <- function(uris, names, chrom, start, end) {\n  parts <- Map(function(uri, nm) {\n    df <- read_bigwig(uri, chrom, start, end)\n    if (nrow(df)) { df$source <- nm; df }\n  }, uris, names)\n  out <- do.call(rbind, parts)\n  out$source <- factor(out$source, levels = unique(names))\n  out\n}",
  read_regions: "# Read one data.frame per region with reader(chrom, start, end), clip each\n# feature to its region (JBrowse cuts features at the region edge) and shift the\n# named coordinate columns onto the cumulative-bp axis region_layout() defines,\n# then rbind into one long frame with a '.region' column. This lets a single\n# ggplot panel span several discontiguous regions on one x-axis. 'reader' returns\n# a genomic-coordinate data.frame; 'coords' names its coordinate columns to\n# clip+shift (point columns are already within range, so clipping is a no-op). A\n# NULL/empty read contributes nothing; an all-empty result keeps the columns.\n# clip = FALSE only shifts (for geometry that must keep its shape at the edges,\n# e.g. Hi-C diamond vertices), otherwise coordinates are clipped to the region.\nread_regions <- function(reader, regions, coords, clip = TRUE) {\n  parts <- lapply(seq_len(nrow(regions)), function(i) {\n    df <- reader(regions$chrom[i], regions$start[i], regions$end[i])\n    if (is.null(df) || !nrow(df)) return(NULL)\n    shift <- regions$offset[i] - regions$start[i]\n    for (col in coords) {\n      v <- df[[col]]\n      if (clip) v <- pmin(pmax(v, regions$start[i]), regions$end[i])\n      df[[col]] <- v + shift\n    }\n    df$.region <- i\n    df\n  })\n  out <- do.call(rbind, parts)\n  if (is.null(out)) {\n    out <- reader(regions$chrom[1], regions$start[1], regions$start[1])\n    out$.region <- integer(0)\n  }\n  out\n}",
  read_vcf: "# Read VCF records in a region via the tabix index (Rsamtools - no\n# VariantAnnotation needed) into data.frame(start, end, ref, alt, type). SV span\n# (END) and SVTYPE come from the INFO column; sequence indels are classed by\n# REF/ALT length. start is 0-based half-open (BED-style).\nread_vcf <- function(uri, chrom, start, end) {\n  info_field <- function(info, key) {\n    pat <- paste0(\"(?:^|;)\", key, \"=([^;]*)\")\n    vapply(info, function(x) {\n      r <- regmatches(x, regexpr(pat, x, perl = TRUE))\n      if (length(r)) sub(pat, \"\\\\1\", r, perl = TRUE) else NA_character_\n    }, character(1), USE.NAMES = FALSE)\n  }\n  lines <- unlist(scanTabix(TabixFile(uri),\n    param = GRanges(chrom, IRanges(start + 1, end))))\n  cols <- if (length(lines)) do.call(rbind, strsplit(lines, \"\\t\", fixed = TRUE))\n          else matrix(character(), 0, 8)\n  pos <- as.integer(cols[, 2]); ref <- cols[, 4]\n  alt <- sub(\",.*\", \"\", cols[, 5]); info <- cols[, 8]\n  symbolic <- grepl(\"^<\", alt)\n  end_info <- suppressWarnings(as.integer(info_field(info, \"END\")))\n  svtype <- info_field(info, \"SVTYPE\")\n  type <- ifelse(symbolic,\n      ifelse(!is.na(svtype), svtype, gsub(\"[<>]\", \"\", alt)),\n    ifelse(nchar(ref) == 1 & nchar(alt) == 1, \"SNV\",\n      ifelse(nchar(ref) < nchar(alt), \"INS\",\n        ifelse(nchar(ref) > nchar(alt), \"DEL\", \"MNV\"))))\n  data.frame(start = pos - 1L,\n             end = ifelse(symbolic & !is.na(end_info), end_info, pos + nchar(ref) - 1L),\n             ref = ref, alt = alt, type = type, stringsAsFactors = FALSE)\n}",
  read_vcf_gt: "# Read per-sample genotypes of a VCF region via the tabix index (Rsamtools - no\n# VariantAnnotation) into a genotype matrix. Sample names come from the '#CHROM'\n# header line; the GT subfield is located in each record's FORMAT column. Each\n# variant's \"most frequent ALT\" allele is found across all samples (matching\n# JBrowse's allele-count coloring). Two modes, mirroring the display's\n# renderingMode:\n#   collapsed (phased = FALSE): one column per sample, each cell classed ref /\n#     het / hom (dosage of that ALT) / other (a secondary ALT) / nocall.\n#   phased   (phased = TRUE):  one column per haplotype (\"<sample> HP<n>\",\n#     n = ploidy of that sample seen in the region), each single allele classed\n#     ref / alt (the most frequent ALT) / other / nocall.\n# Also returns per-site minor-allele-frequency and no-call missingness (no-calls\n# excluded from the MAF denominator, as in JBrowse) so sites can be filtered, and\n# each site's 0-based half-open genomic span (start/end; symbolic SVs use INFO\n# END) for displays that draw at genomic position rather than by column index.\nread_vcf_gt <- function(uri, chrom, start, end, phased = FALSE) {\n  tf <- TabixFile(uri)\n  hdr <- headerTabix(tf)$header\n  header_cols <- strsplit(sub(\"^#\", \"\", hdr[length(hdr)]), \"\\t\", fixed = TRUE)[[1]]\n  samples <- header_cols[-(1:9)]\n  ns <- length(samples)\n  lines <- unlist(scanTabix(tf, param = GRanges(chrom, IRanges(start + 1, end))))\n  if (!length(lines)) {\n    cols <- if (phased) character() else samples\n    return(list(cls = matrix(character(), 0, length(cols)),\n                dose = matrix(numeric(), 0, length(cols)),\n                maf = numeric(), missingness = numeric(), has_alt = logical(),\n                start = integer(), end = integer(), samples = cols))\n  }\n  m <- do.call(rbind, strsplit(lines, \"\\t\", fixed = TRUE))\n  pos <- as.integer(m[, 2]); ref <- m[, 4]; alt <- sub(\",.*\", \"\", m[, 5])\n  symbolic <- grepl(\"^<\", alt)\n  end_info <- suppressWarnings(as.integer(vapply(m[, 8], function(x) {\n    r <- regmatches(x, regexpr(\"(?:^|;)END=([^;]*)\", x, perl = TRUE))\n    if (length(r)) sub(\".*END=\", \"\", r) else NA_character_\n  }, character(1), USE.NAMES = FALSE)))\n  vstart <- pos - 1L\n  vend <- ifelse(symbolic & !is.na(end_info), end_info, pos + nchar(ref) - 1L)\n  gt_field <- vapply(strsplit(m[, 9], \":\", fixed = TRUE),\n                     function(f) match(\"GT\", f), integer(1))\n  nv <- nrow(m)\n  maf <- numeric(nv); missingness <- numeric(nv); has_alt <- logical(nv)\n  toks_all <- vector(\"list\", nv); mfa_all <- character(nv)\n  for (i in seq_len(nv)) {\n    raw <- m[i, 10:(9 + ns)]\n    gi <- gt_field[i]\n    gts <- if (is.na(gi)) raw else\n      vapply(strsplit(raw, \":\", fixed = TRUE), function(x) x[gi], character(1))\n    toks <- strsplit(gts, \"[/|]\")\n    toks_all[[i]] <- toks\n    all_alleles <- unlist(toks)\n    called <- all_alleles[all_alleles != \".\"]\n    alt_tab <- table(called[called != \"0\"])\n    mfa_all[i] <- if (length(alt_tab)) names(alt_tab)[which.max(alt_tab)] else NA_character_\n    has_alt[i] <- !is.na(mfa_all[i])\n    counts <- sort(as.integer(table(called)), decreasing = TRUE)\n    maf[i] <- if (length(counts) >= 2) counts[2] / length(called) else 0\n    missingness[i] <- sum(all_alleles == \".\") / length(all_alleles)\n  }\n  if (phased) {\n    # per-sample ploidy = max allele count across sites (samples never called\n    # anywhere default to diploid), then one HP column per haplotype\n    ploidy <- rep(2L, ns)\n    for (i in seq_len(nv)) ploidy <- pmax(ploidy, lengths(toks_all[[i]]))\n    hap_sample <- rep(seq_len(ns), ploidy)\n    hap_idx <- unlist(lapply(ploidy, seq_len))\n    hap_names <- paste0(samples[hap_sample], \" HP\", hap_idx - 1L)\n    # site-by-haplotype allele matrix, then class every cell in one vectorized\n    # pass (single allele per cell: ref / alt = most-frequent ALT / other / nocall)\n    allele <- do.call(rbind, lapply(toks_all, function(toks)\n      mapply(function(s, k) toks[[s]][k], hap_sample, hap_idx)))\n    mfa <- matrix(mfa_all, nv, length(hap_sample))\n    is_ref <- !is.na(allele) & allele == \"0\"\n    is_alt <- !is.na(allele) & allele != \"0\" & allele != \".\" & allele == mfa\n    is_oth <- !is.na(allele) & allele != \"0\" & allele != \".\" & allele != mfa\n    cls <- matrix(\"nocall\", nv, length(hap_sample))\n    cls[is_ref] <- \"ref\"; cls[is_alt] <- \"alt\"; cls[is_oth] <- \"other\"\n    dose <- ifelse(is_ref, 0, ifelse(is_alt | is_oth, 1, NA_real_))\n    rownames(cls) <- seq_len(nv); colnames(cls) <- hap_names\n    return(list(cls = cls, dose = dose, maf = maf, missingness = missingness,\n                has_alt = has_alt, start = vstart, end = vend, samples = hap_names))\n  }\n  cls <- matrix(\"nocall\", nv, ns); dose <- matrix(NA_real_, nv, ns)\n  for (i in seq_len(nv)) {\n    toks <- toks_all[[i]]; mfa <- mfa_all[i]\n    for (j in seq_len(ns)) {\n      a <- toks[[j]]\n      if (all(a == \".\")) next\n      d <- if (is.na(mfa)) 0L else sum(a == mfa)\n      other <- if (is.na(mfa)) 0L else sum(a != \"0\" & a != \".\" & a != mfa)\n      dose[i, j] <- d\n      cls[i, j] <- if (other > 0) \"other\" else if (d == 0) \"ref\" else if (d == 1) \"het\" else \"hom\"\n    }\n  }\n  rownames(cls) <- seq_len(nv); colnames(cls) <- samples\n  list(cls = cls, dose = dose, maf = maf, missingness = missingness,\n       has_alt = has_alt, start = vstart, end = vend, samples = samples)\n}",
  region_dividers: "# Vertical lines marking the boundary between consecutive regions on the\n# cumulative axis (drawn in the middle of each inter-region gap). Nothing for a\n# single region.\nregion_dividers <- function(regions) {\n  if (nrow(regions) <= 1) return(geom_blank())\n  geom_vline(xintercept = head(regions$cum_end, -1) + regions$gap[1] / 2,\n             color = \"grey70\", linewidth = 0.4)\n}",
  region_layout: "# Lay a set of displayed regions out on one continuous \"cumulative bp\" x-axis,\n# the way JBrowse concatenates several regions in a single linear view: each\n# region occupies a span proportional to its bp width, with a small gap between\n# them. 'regions' is a data.frame(chrom, start, end) (0-based half-open); this\n# adds offset (the region's left edge on the cumulative axis), width, gap, and\n# cum_start/cum_end. The first region is anchored at its own genomic start, so a\n# lone region keeps native genomic coordinates (a single-region figure is\n# unchanged). cum_pos for a position p in region i is offset[i] + (p - start[i]).\nregion_layout <- function(regions, gap_frac = 0.012) {\n  w <- regions$end - regions$start\n  gap <- max(1, round(sum(w) * gap_frac))\n  regions$offset <- regions$start[1] + head(cumsum(c(0, w + gap)), length(w))\n  regions$width <- w; regions$gap <- gap\n  regions$cum_start <- regions$offset; regions$cum_end <- regions$offset + w\n  regions\n}",
  region_ruler: "# A thin top panel naming each region over its span on the cumulative axis (a\n# bar + the locus label), shown above the tracks when more than one region is\n# drawn. Shares region_scale/coord so it aligns with the track panels below.\nregion_ruler <- function(regions) {\n  lab <- data.frame(x = (regions$cum_start + regions$cum_end) / 2,\n    label = sprintf(\"%s:%s-%s\", regions$chrom, format(regions$start + 1, big.mark = \",\"),\n                    format(regions$end, big.mark = \",\")))\n  ggplot(regions) +\n    geom_segment(aes(x = cum_start, xend = cum_end, y = 0, yend = 0),\n                 color = \"grey40\", linewidth = 0.8) +\n    geom_text(data = lab, aes(x, 0.35, label = label), size = 3, color = \"grey20\") +\n    region_scale(regions) + region_dividers(regions) +\n    coord_cartesian(xlim = region_xlim(regions), ylim = c(-0.2, 0.9), clip = \"off\") +\n    theme_void()\n}",
  region_scale: "# x-axis scale for the cumulative-bp axis: a lone region gets an ordinary\n# bp/kb/Mb axis (native genomic coords); several regions get a few pretty genomic\n# breaks per region positioned at their cumulative x, each labeled with its own\n# genomic coordinate (so every region reads in its native coordinates). Interior\n# breaks only (region edges dropped) so labels don't collide with the dividers.\nregion_scale <- function(regions) {\n  fmt <- scales::label_number(scale_cut = scales::cut_si(\"b\"))\n  if (nrow(regions) == 1) {\n    return(scale_x_continuous(labels = fmt, expand = expansion(mult = 0.01)))\n  }\n  br <- do.call(rbind, lapply(seq_len(nrow(regions)), function(i) {\n    g <- pretty(c(regions$start[i], regions$end[i]), n = 4)\n    g <- g[g > regions$start[i] & g < regions$end[i]]\n    if (!length(g)) g <- round((regions$start[i] + regions$end[i]) / 2)\n    data.frame(x = regions$offset[i] + (g - regions$start[i]), lab = fmt(g))\n  }))\n  scale_x_continuous(breaks = br$x, labels = br$lab, expand = expansion(mult = 0.005))\n}",
  region_title: "# Figure title: the locus for a single region, else a region count.\nregion_title <- function(regions) {\n  if (nrow(regions) == 1)\n    sprintf(\"%s:%s-%s\", regions$chrom[1], format(regions$start[1] + 1, big.mark = \",\"),\n            format(regions$end[1], big.mark = \",\"))\n  else sprintf(\"%d regions \\u00b7 %s bp\", nrow(regions),\n               format(sum(regions$end - regions$start), big.mark = \",\"))\n}",
  region_xlim: "# Cumulative-axis x range spanning every region, with a hair of padding.\nregion_xlim <- function(regions) {\n  pad <- sum(regions$width) * 0.004\n  c(min(regions$offset) - pad, max(regions$cum_end) + pad)\n}",
  resolve_chrom: "# Translate a canonical chromosome name to the one a particular track's file\n# uses. JBrowse resolves refname aliases (chr1 vs 1 vs NC_000001.11) per file;\n# 'aliases' is a named vector canonical -> file name for one track. A name not\n# in it passes through unchanged, so the same plot_region() call reads correctly\n# from files with different contig naming.\nresolve_chrom <- function(chrom, aliases) {\n  if (chrom %in% names(aliases)) aliases[[chrom]] else chrom\n}",
  snp_freq_threshold: "# JBrowse's depth-dependent low-frequency threshold (featureFrequencyThreshold):\n# a mismatch base is significant only above 80% of depth below 10x, easing to 30%\n# at >=30x. Drives the pileup mismatch fade (mismatch_fade_alpha), not the coverage\n# panel (which shows every fraction).\nsnp_freq_threshold <- function(depth) {\n  ifelse(depth < 10, 0.8, ifelse(depth >= 30, 0.3, 0.8 + (depth - 10) / 20 * (0.3 - 0.8)))\n}",
  sorted_pileup_layout: "# Localized sort layout - JBrowse's \"Sort by...\" at the center line. Reads\n# overlapping sort_pos are ordered by the criterion and placed first (each on its\n# own row, since they all cover sort_pos), then the remaining reads fill the gaps\n# around them in genomic order (first-fit-lowest-row, like disjointBins). Mirrors\n# JBrowse's computeSortedLayout. A sort_pos of -1 (no center line) leaves every\n# read in genomic order. Note the baked sort_pos is the exported locus's column -\n# move it to re-sort elsewhere.\n#\n# sort_type, and the frame each reads its key from:\n#   \"position\"  read start, ascending\n#   \"strand\"    forward strand first\n#   \"base\"      the read's char at sort_pos: a deletion '*' first, then the\n#               MD-tag mismatch base by ASCII A,C,G,N,T (from 'mm'), then\n#               reference-matching reads. Deletions spanning sort_pos come from\n#               the CIGAR 'indels'.\n#   \"insertion\" length of the insertion at sort_pos (from 'indels', type \"I\")\n#   \"softclip\"  length of the soft clip at sort_pos (from 'clips', type \"S\")\n#   \"hardclip\"  length of the hard clip at sort_pos (from 'clips', type \"H\")\n#   \"tag\"       reads$sort_tag (see bam_tag_values), descending\n#\n# Every branch returns a numeric key sorted ASCENDING by one order() call, with\n# Inf meaning \"this read has no key\". That reproduces JBrowse's\n# sortByMapWithUnknownsLast: reads carrying the sorted-on feature come first,\n# reads without it keep genomic order behind them. A descending criterion\n# (interbase length, numeric tag) is keyed negative rather than sorted separately.\nsorted_pileup_layout <- function(reads, sort_pos, sort_type = \"position\", mm = NULL,\n                                 indels = NULL, clips = NULL) {\n  keep <- if (is.null(reads$keep)) rep(TRUE, nrow(reads)) else reads$keep\n  ov <- which(keep & reads$start <= sort_pos & reads$end > sort_pos)\n  key <- switch(sort_type,\n    strand = ifelse(reads$strand[ov] == \"-\", 1L, 0L),\n    base = {\n      # JBrowse ranks the read's char at sort_pos by ASCII: '*' deletion (42),\n      # then the mismatch base A(65) C(67) G(71) N(78) T(84), reference-matching\n      # reads (no key) last. Inf sentinel sorts those last via order() below.\n      k <- rep(Inf, length(ov))\n      hit <- if (is.null(mm)) NULL else mm[mm$refpos == sort_pos, , drop = FALSE]\n      if (!is.null(hit) && nrow(hit)) {\n        # mm keeps every read's rows (dropping them would desync the read_index\n        # join), so a mismatch here may belong to a read \"Filter by\" rejected -\n        # which is not in ov and has no row to rank. Drop those NA matches.\n        hi <- match(hit$read_index, ov); ok <- !is.na(hi)\n        k[hi[ok]] <-\n          vapply(toupper(hit$base[ok]), utf8ToInt, integer(1), USE.NAMES = FALSE)\n      }\n      # a deletion spanning sort_pos ranks as '*' (42), but only for reads without\n      # a mismatch base there (JBrowse's !baseAtPos.has(readIdx) guard)\n      del <- if (is.null(indels)) NULL else indels[indels$type == \"D\" &\n        indels$refpos <= sort_pos & indels$refpos + indels$length > sort_pos, , drop = FALSE]\n      if (!is.null(del) && nrow(del)) {\n        di <- match(del$read_index, ov); di <- di[!is.na(di)]\n        di <- di[is.infinite(k[di])]\n        k[di] <- 42\n      }\n      k\n    },\n    insertion = ,\n    softclip = ,\n    hardclip = {\n      # The interbase sorts rank by the event's length AT sort_pos, longest first\n      # (JBrowse's buildSortKeyMap desc = TRUE), reads without one last. These are\n      # exact column matches, not span tests: bam_indels' refpos for an \"I\" and\n      # bam_clips' pos for an S/H are the very interbase columns JBrowse keys on\n      # (a left clip sits on the read's first aligned base, a right clip just past\n      # its last).\n      src <- if (sort_type == \"insertion\") {\n        if (is.null(indels)) NULL else indels[indels$type == \"I\", , drop = FALSE]\n      } else if (is.null(clips)) {\n        NULL\n      } else {\n        clips[clips$type == if (sort_type == \"softclip\") \"S\" else \"H\", , drop = FALSE]\n      }\n      pos_col <- if (sort_type == \"insertion\") \"refpos\" else \"pos\"\n      k <- rep(Inf, length(ov))\n      if (!is.null(src) && nrow(src)) {\n        hit <- src[src[[pos_col]] == sort_pos, , drop = FALSE]\n        if (nrow(hit)) {\n          # one read can carry several events at a column; JBrowse keys the longest\n          best <- tapply(hit$length, hit$read_index, max)\n          bi <- match(as.integer(names(best)), ov); ok <- !is.na(bi)\n          k[bi[ok]] <- -as.numeric(best)[ok]   # negated: longest sorts first\n        }\n      }\n      k\n    },\n    tag = {\n      # JBrowse sorts the sort-tag descending, numerically when every value in\n      # play parses as a number - a missing tag reads as \"\" and counts as 0\n      # without forcing string mode (one numeric-looking value must not decide the\n      # mode for a column of string tags). reads$sort_tag is the per-read value\n      # from bam_tag_values, \"\" where the read lacks the tag. Unlike the branches\n      # above there is no \"unknowns last\": a missing tag sorts as 0 / \"\".\n      v <- if (is.null(reads$sort_tag)) rep(\"\", length(ov)) else reads$sort_tag[ov]\n      v[is.na(v)] <- \"\"\n      num <- suppressWarnings(as.numeric(v))\n      if (all(v == \"\" | !is.na(num))) {\n        num[is.na(num)] <- 0\n        -num\n      } else {\n        # xtfrm ranks strings by the collation order order() would use, so negating\n        # it sorts them descending like JBrowse's localeCompare(b, a)\n        -xtfrm(v)\n      }\n    },\n    reads$start[ov])\n  order_idx <- c(ov[order(key)], setdiff(which(keep), ov))\n\n  # greedy first-fit-lowest-row placement in that order: each row keeps the\n  # intervals placed on it so far, and a read takes the lowest row it clears.\n  # Filtered reads (not in order_idx) keep an NA row and go undrawn.\n  starts <- ends <- list()\n  row <- rep(NA_integer_, nrow(reads))\n  for (i in order_idx) {\n    s <- reads$start[i]; e <- reads$end[i]\n    r <- 1L\n    while (r <= length(starts) && any(s < ends[[r]] & e > starts[[r]])) r <- r + 1L\n    if (r > length(starts)) { starts[[r]] <- numeric(0); ends[[r]] <- numeric(0) }\n    starts[[r]] <- c(starts[[r]], s); ends[[r]] <- c(ends[[r]], e)\n    row[i] <- r\n  }\n  reads$row <- row\n  reads\n}",
  vcf_layout: "# Row-pack variants so overlapping ones stack (IRanges::disjointBins).\nvcf_layout <- function(v) {\n  v$row <- if (nrow(v)) disjointBins(IRanges(v$start + 1L, pmax(v$end, v$start + 1L))) else integer()\n  v\n}",
}
